import fs from 'node:fs';import path from 'node:path';import {createHash}from'node:crypto';import{spawnSync}from'node:child_process';import JSZip from'jszip';import{exportSource}from'./export-source.mjs';import{APP_ROOT,beneath,noLinks}from'./environment.mjs';
export const assets=['Kinseed-Windows-source.zip','SOURCE_FILES_SHA256.json','ACCEPTANCE.md','VERIFICATION.json','SHA256SUMS.txt'];
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const sourceBlobSha=b=>{const normalized=Buffer.from(b.toString('latin1').replaceAll('\r\n','\n'),'latin1');return createHash('sha1').update(Buffer.concat([Buffer.from('blob '+normalized.length+'\0'),normalized])).digest('hex');};
export function releaseVersion(version){const m=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-preview\.(0|[1-9]\d*))?$/.exec(version??'');if(!m)throw Error('RELEASE_VERSION');return {version,tag:'v'+version,prerelease:m[4]!==undefined};}
export function parseAcceptance(nodeLog,uiLog,expectedScripts){const summary=key=>{const found=[...nodeLog.matchAll(new RegExp('(?:ℹ|#) '+key+' (\\d+)','g'))];return Number(found.at(-1)?.[1]??NaN);};const tests=summary('tests'),pass=summary('pass');if(!Number.isSafeInteger(tests)||tests<1||pass!==tests||summary('fail')!==0||summary('skipped')!==0||summary('cancelled')!==0)throw Error('NODE_ACCEPTANCE_NOT_PASS');const ui=uiLog.split(/\r?\n/).filter(l=>l.startsWith('{')).map(l=>JSON.parse(l));if(ui.length!==expectedScripts||ui.some(r=>r.status==='FAIL'||r.errors?.length||Object.values(r.checks??{}).some(v=>v!==true)))throw Error('UI_ACCEPTANCE_NOT_PASS');const checks=ui.reduce((n,r)=>n+Object.keys(r.checks??{}).length,0);if(checks<1)throw Error('UI_ACCEPTANCE_EMPTY');return {node_tests:tests,node_pass:pass,node_fail:0,node_skipped:0,ui_scripts:ui.length,ui_checks:checks};}
export function safeEntry(name){return typeof name==='string'&&name.length>0&&!name.includes('\\')&&!name.includes(':')&&!name.startsWith('/')&&!name.split('/').some(x=>x==='..'||x==='.'||x==='')&&!/(?:^|\/)(?:\.private|node_modules|runtime_v1_2|runtime_reports|\.git)(?:\/|$)|\.(?:sqlite|jsonl|pem|key)$|development\.local\.json/.test(name);}
export async function verifyBundle(dir,{expectedSha,expectedVersion}={}){const names=fs.readdirSync(dir).sort();if(JSON.stringify(names)!==JSON.stringify([...assets].sort()))throw Error('RELEASE_ASSET_SET');const sums=fs.readFileSync(path.join(dir,'SHA256SUMS.txt'),'utf8').trim().split('\n'),seen=new Set();for(const line of sums){const m=/^([a-f0-9]{64})  ([A-Za-z0-9_.-]+)$/.exec(line);if(!m||m[2]==='SHA256SUMS.txt'||!assets.includes(m[2])||seen.has(m[2]))throw Error('ASSET_SUM_FORMAT');seen.add(m[2]);if(sha256(fs.readFileSync(path.join(dir,m[2])))!==m[1])throw Error('ASSET_SHA');}if(seen.size!==assets.length-1)throw Error('ASSET_SUM_MISSING');const verification=JSON.parse(fs.readFileSync(path.join(dir,'VERIFICATION.json'))),version=releaseVersion(verification.version);if(!/^[a-f0-9]{40}$/.test(verification.source_sha)||verification.tag!==version.tag||verification.prerelease!==version.prerelease||expectedSha&&verification.source_sha!==expectedSha||expectedVersion&&verification.version!==expectedVersion)throw Error('BUNDLE_SOURCE_VERSION');const manifest=JSON.parse(fs.readFileSync(path.join(dir,'SOURCE_FILES_SHA256.json'))),zip=await JSZip.loadAsync(fs.readFileSync(path.join(dir,'Kinseed-Windows-source.zip')),{checkCRC32:true});const files=Object.values(zip.files).filter(f=>!f.dir);if(files.length!==Object.keys(manifest).length||files.length>2000)throw Error('ZIP_MANIFEST_SET');const source_blob_sha1={};let total=0;for(const f of files){if(f.unsafeOriginalName&&f.unsafeOriginalName!==f.name||!f.name.startsWith('Kinseed/')||!safeEntry(f.name.slice(8)))throw Error('ZIP_PATH_SCOPE');const rel=f.name.slice(8),bytes=await f.async('nodebuffer');total+=bytes.length;source_blob_sha1[rel]=sourceBlobSha(bytes);if(bytes.length>16*1024*1024||total>64*1024*1024||manifest[rel]!==sha256(bytes))throw Error('ZIP_SOURCE_SHA');}for(const f of Object.keys(manifest))if(!safeEntry(f)||!zip.file('Kinseed/'+f)||!/^[a-f0-9]{64}$/.test(manifest[f]))throw Error('ZIP_MANIFEST_SCOPE');const pkg=JSON.parse(await zip.file('Kinseed/package.json').async('string')),lock=JSON.parse(await zip.file('Kinseed/package-lock.json').async('string'));if(pkg.version!==version.version||lock.version!==pkg.version||lock.packages[''].version!==pkg.version)throw Error('ZIP_PACKAGE_VERSION');return {status:'PASS',verification,files:files.length,source_blob_sha1,asset_sha256:Object.fromEntries(assets.map(n=>[n,sha256(fs.readFileSync(path.join(dir,n)))]))};}
export async function buildBundle({root=APP_ROOT,output,sourceSha,runUrl,nodeLog,uiLog,fixture=false}){const pkg=JSON.parse(fs.readFileSync(path.join(root,'package.json'))),version=releaseVersion(pkg.version),policy=JSON.parse(fs.readFileSync(path.join(root,'.github/release-policy.json')));if(policy.channel!==(version.prerelease?'preview':'stable'))throw Error('CHANNEL_MISMATCH');if(!/^[a-f0-9]{40}$/.test(sourceSha)||!new RegExp('^https://github.com/'+policy.repository+'/actions/runs/[0-9]+$').test(runUrl))throw Error('RELEASE_PROVENANCE');if(!fixture){if(process.env.GITHUB_ACTIONS!=='true'||process.env.GITHUB_SHA!==sourceSha)throw Error('CI_PROVENANCE_REQUIRED');const rev=spawnSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}),dirty=spawnSync('git',['status','--porcelain'],{cwd:root,encoding:'utf8'});if(rev.status!==0||rev.stdout.trim()!==sourceSha||dirty.status!==0||dirty.stdout.trim())throw Error('SOURCE_NOT_CLEAN');}if(!beneath(path.join(root,'.private'),path.resolve(output)))throw Error('BUNDLE_OUTPUT_PRIVATE');noLinks(root,output);if(fs.existsSync(output))throw Error('BUNDLE_OUTPUT_EXISTS');const acceptance=parseAcceptance(nodeLog,uiLog,pkg.scripts['test:ui'].split('&&').length),exported=exportSource(root),zip=new JSZip();for(const rel of Object.keys(exported.files).sort())zip.file('Kinseed/'+rel,fs.readFileSync(path.join(exported.destination,rel)),{date:new Date('2000-01-01T00:00:00Z'),createFolders:false});fs.mkdirSync(output,{recursive:true});fs.writeFileSync(path.join(output,assets[0]),await zip.generateAsync({type:'nodebuffer',compression:'DEFLATE',compressionOptions:{level:9},platform:'DOS'}));fs.writeFileSync(path.join(output,assets[1]),JSON.stringify(exported.files,null,2)+'\n');const verification={schema:1,...version,source_sha:sourceSha,ci_run_url:runUrl,build_mode:fixture?'synthetic-package-test':'github-actions',acceptance,ai_self_acceptance:true,independent_human:'NOT_RUN',native_language_review:'NOT_RUN',second_physical_windows:'NOT_RUN',new_real_model_or_paid_acceptance:'NOT_RUN',source_file_count:exported.count};fs.writeFileSync(path.join(output,assets[3]),JSON.stringify(verification,null,2)+'\n');fs.writeFileSync(path.join(output,assets[2]),`# ${version.tag} acceptance\n\nSource: ${sourceSha}\n\nWindows CI: ${runUrl}\n\n${acceptance.node_tests} Node tests, ${acceptance.ui_scripts} browser scripts / ${acceptance.ui_checks} checks passed.\n\nAI project self-acceptance. No independent human, native-language or second physical Windows acceptance. This packaging run does not claim new real-model or paid-service verification. See the source version's acceptance document for earlier qualified scope.\n\nThe ZIP contains source and lockfile, not runtime, credentials, individuals, model weights or dependencies.\n`);fs.writeFileSync(path.join(output,assets[4]),assets.filter(n=>n!==assets[4]).map(n=>sha256(fs.readFileSync(path.join(output,n)))+'  '+n).join('\n')+'\n');return verifyBundle(output,{expectedSha:sourceSha,expectedVersion:pkg.version});}
if(process.argv[1]&&path.resolve(process.argv[1])===import.meta.filename){const [mode,...args]=process.argv.slice(2),a=Object.fromEntries(args.map(s=>{const i=s.indexOf('=');return[s.slice(0,i),s.slice(i+1)];}));if(mode==='build'){console.log(JSON.stringify(await buildBundle({output:path.resolve(APP_ROOT,'.private/release-candidate'),sourceSha:a.sha,runUrl:a.run,nodeLog:fs.readFileSync(path.join(APP_ROOT,'.private/release-node.log'),'utf8'),uiLog:fs.readFileSync(path.join(APP_ROOT,'.private/release-ui.log'),'utf8')}),null,2));}else if(mode==='verify'){console.log(JSON.stringify(await verifyBundle(path.resolve(a.dir),{expectedSha:a.sha}),null,2));}else throw Error('RELEASE_BUNDLE_MODE');}
